const path=require('node:path');
require(path.join(process.cwd(),'scripts/ingestion/isolated-runtime.cjs'));
const assert=require('node:assert/strict');
const fs=require('node:fs');
const db=require(path.join(process.cwd(),'src/lib/prisma')).default;
const {prepareStageFixture}=require(path.join(process.cwd(),'scripts/ingestion/capacity-stages.cjs'));
const {processPendingGeneralJobs}=require(path.join(process.cwd(),'src/lib/jobs/queue'));
(async()=>{
  const fixture=await prepareStageFixture(db,'effects-only',300);
  const finishProfile=await require(path.join(process.cwd(),'scripts/ingestion/database-profile.cjs'))(db);
  const started=performance.now(),cpu=process.cpuUsage();
  await db.$executeRaw`UPDATE "BackgroundJob" SET "scheduledAt"=clock_timestamp() WHERE type='SCHEDULED_TASK'`;
  let cycles=0,processed=0,failed=0;
  while(performance.now()-started<120000){
    const result=await processPendingGeneralJobs(100,15);
    cycles++; processed+=result.processed;failed+=result.failed;
    if(result.failed>0||result.total===0)break;
  }
  const elapsedMs=performance.now()-started,usage=process.cpuUsage(cpu);
  const databaseProfile=await finishProfile();
  const jobs=await db.backgroundJob.groupBy({by:['type','status'],_count:{_all:true}});
  const count=(type,status)=>jobs.find(r=>r.type===type&&r.status===status)?._count._all||0;
  const passed=failed===0&&count('SCHEDULED_TASK','COMPLETED')===1500&&count('WAR_ROOM_PROVIDER_EVENT','COMPLETED')===600&&count('RUNBOOK','PENDING')===300&&jobs.reduce((n,r)=>n+r._count._all,0)===2400;
  const evidence={variant:process.env.DISPATCH_VARIANT,sourceRevision:process.env.DISPATCH_SOURCE_REVISION,measuredAt:new Date().toISOString(),passed,fixture,elapsedMs,cpuMs:(usage.user+usage.system)/1000,cycles,processed,failed,jobs,unitsPerSecond:300000/elapsedMs,queriesPerUnit:databaseProfile.totalQueryCalls/300,databaseProfile,scope:'Controlled host-process general-queue diagnostic, 300 default 10KB critical-trigger incidents, no providers/users/Automation; 1,500 parents plus 600 generated child jobs must finish, 300 runbook jobs intentionally held. Same archived source except queue dispatcher; no native-image, provider, full-stack or sustained capacity certification.'};
  assert.ok(process.env.DISPATCH_EVIDENCE?.startsWith('/private/tmp/ingestion-dispatch-'));
  fs.writeFileSync(process.env.DISPATCH_EVIDENCE,JSON.stringify(evidence,null,2));
  assert.ok(passed,'General dispatch probe failed reconciliation');
})().catch(error=>{console.error(error);process.exitCode=1}).finally(()=>db.$disconnect());

